pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(uint256 fundAmount) public {
        fundAmount = bound(fundAmount, 1, 10 ether);

        address payer = address(0xBEEF);
        vm.deal(payer, fundAmount);

        vm.prank(payer);
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent, "funding failed in setup");

        assert(address(c).balance == fundAmount);

        address recipient = address(0xCAFE);

        uint256 beforeRecipient = recipient.balance;

        c.withdrawAll(recipient);

        assertTrue(address(c).balance == 0);

    }
}
